import { Component, createEffect, createSignal, on } from "solid-js";

import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SimpleButton } from "#core/ui-next/debug/simple-button.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface IModelProxy {
	value: object;
	readonly name: string;
	readonly id: number;
}

export interface ObjectEditorProps {
	proxy?: IModelProxy;
	class: string;
}

export const ObjectEditorComponent: Component<ObjectEditorProps> = (props) => {
	let textArea: HTMLTextAreaElement | undefined;
	const [autoRefresh, setAutoRefresh] = createSignal(false);
	const [jsonValue, setJsonValue] = createSignal("");

	function updateModel() {
		if (textArea && props.proxy) {
			props.proxy.value = JSON.parse(textArea.value);
		}
	}

	function forceRefresh() {
		if (props.proxy) {
			const value = props.proxy.value;
			const json = JSON.stringify(value, null, 2);
			setJsonValue(json);
		}
	}

	createEffect(() => {
		if (autoRefresh() && props.proxy) {
			const json = JSON.stringify(props.proxy.value, null, 2);
			setJsonValue(json);
		}
	});

	createEffect(on(() => jsonValue(), updateTextAreaSize));

	function updateTextAreaSize() {
		waitForLayout(() => {
			if (textArea) {
				textArea.style.height = `${textArea?.scrollHeight}px`;
			}
		});
	}

	return (
		<div class="flex flex-col flex-auto">
			<div class="flex flex-row">
				<RadioButton
					class="mx-1 my-2"
					isChecked={autoRefresh()}
					onActivate={() => setAutoRefresh((v) => !v)}
				>
					Auto
				</RadioButton>

				<SimpleButton
					class="ml-4 mr-2 my-2"
					onActivate={forceRefresh}
				>
					Refresh
				</SimpleButton>
				<SimpleButton
					class="m-2"
					onActivate={updateModel}
				>
					Push
				</SimpleButton>
			</div>
			<ScrollArea class="flex-auto m-2">
				<textarea
					class="w-full h-auto"
					ref={(r) => (textArea = r)}
					onInput={updateTextAreaSize}
				>
					{jsonValue()}
				</textarea>
			</ScrollArea>
		</div>
	);
};

export const ObjectEditor = ComponentRegistry.register({
	name: "ObjectEditor",
	createInstance: ObjectEditorComponent,
});
